    public function pointOfSaleOptions(): array
    {
        $products=$this->db->query("SELECT p.id,p.title,p.item_id FROM uniform_catalog_products p WHERE p.status='active' ORDER BY p.title")->fetchAll(PDO::FETCH_ASSOC);$sizes=$this->db->query("SELECT p.id product_id,NULL variant_id,us.id size_id,us.size,us.size_label,us.unit_price,GREATEST(0,us.quantity_available-us.quantity_reserved) available FROM uniform_catalog_products p JOIN uniform_sizes us ON us.item_id=p.item_id WHERE p.status='active' UNION ALL SELECT v.product_id,v.id,us.id,us.size,us.size_label,us.unit_price,GREATEST(0,us.quantity_available-us.quantity_reserved) FROM uniform_catalog_variants v JOIN uniform_sizes us ON us.item_id=v.item_id JOIN uniform_catalog_products p ON p.id=v.product_id WHERE p.status='active' AND v.status='active'")->fetchAll(PDO::FETCH_ASSOC);foreach($products as &$p)$p['sizes']=array_values(array_filter($sizes,fn($s)=>(int)$s['product_id']===(int)$p['id']));unset($p);$staff=$this->db->query("SELECT u.id,CONCAT(p.first_name,' ',p.last_name) name,u.username FROM users u JOIN persons p ON p.id=u.person_id WHERE u.status='active' ORDER BY p.first_name,p.last_name")->fetchAll(PDO::FETCH_ASSOC);return ['products'=>$products,'staff'=>$staff,'payment_options'=>$this->paymentOptions(true)];
    }

    public function pointOfSale(array $data,int $actor): array
    {
        $channel=(string)($data['channel']??'cash');if(!in_array($channel,['cash','bank_transfer','cheque'],true))throw new RuntimeException('Counter sales require cash, bank transfer or cheque confirmation');$account=(new FinancialAccountService($this->db))->requireFor((int)($data['financial_account_id']??0),'uniforms',$channel);$staffBuyer=(int)($data['staff_buyer_id']??0);$studentId=(int)($data['student_id']??0)?:null;$items=$data['items']??[];if(!is_array($items)||!$items)throw new RuntimeException('Add at least one product');$this->db->beginTransaction();try{$lines=[];$total=0.0;foreach($items as $item){$qty=(int)($item['quantity']??0);if($qty<1)throw new RuntimeException('Every sale line requires a quantity');$line=$this->purchasableLine((int)($item['product_id']??0),(int)($item['variant_id']??0)?:null,(int)($item['size_id']??0),'staff',true);if((int)$line['quantity_available']-(int)$line['quantity_reserved']<$qty)throw new RuntimeException($line['title'].' does not have enough stock');$line['quantity']=$qty;$line['line_total']=$qty*(float)$line['unit_price'];$total+=(float)$line['line_total'];$lines[]=$line;}$ref='KPS-POS-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(4)));$this->db->prepare("INSERT INTO catalog_orders(order_reference,buyer_type,buyer_id,student_id,source,status,payment_status,subtotal,total_amount,customer_note,placed_by,paid_at,fulfilled_at) VALUES(?,?,?,?,'physical','fulfilled','paid',?,?,?,?,NOW(),NOW())")->execute([$ref,$staffBuyer?'staff':'walk_in',$staffBuyer?:null,$studentId,$total,$total,$data['note']??null,$actor]);$orderId=(int)$this->db->lastInsertId();$insert=$this->db->prepare('INSERT INTO catalog_order_items(order_id,product_id,variant_id,size_id,item_id,product_title,variant_name,size_label,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?,?,?,?,?,?)');foreach($lines as $line){$insert->execute([$orderId,$line['product_id'],$line['variant_id']?:null,$line['size_id'],$line['item_id'],$line['title'],$line['variant_name'],$line['size_label']?:$line['size'],$line['quantity'],$line['unit_price'],$line['line_total']]);$lineId=(int)$this->db->lastInsertId();$this->db->prepare('UPDATE uniform_sizes SET quantity_available=quantity_available-?,quantity_sold=quantity_sold+? WHERE id=?')->execute([$line['quantity'],$line['quantity'],$line['size_id']]);$this->db->prepare('UPDATE inventory_items SET current_quantity=GREATEST(0,current_quantity-?) WHERE id=?')->execute([$line['quantity'],$line['item_id']]);if($studentId)$this->db->prepare("INSERT INTO uniform_sales(student_id,item_id,size,quantity,unit_price,payment_status,sale_date,received_date,receipt_no,sold_by,notes) VALUES(?,?,?,?,?,'paid',CURDATE(),CURDATE(),?,?,?)")->execute([$studentId,$line['item_id'],$line['size_label']?:$line['size'],$line['quantity'],$line['unit_price'],$ref.'-'.$lineId,$actor,'Physical catalogue order '.$ref]);}$this->db->prepare("INSERT INTO catalog_payment_attempts(order_id,channel,amount,status,idempotency_reference,provider_transaction_id,financial_account_id,request_json,created_by,confirmed_at) VALUES(?,?,?,'confirmed',?,?,?,?,?,NOW())")->execute([$orderId,$channel,$total,$ref,trim((string)($data['payment_reference']??$ref)),(int)$account['id'],json_encode($data),$actor]);$paymentId=(int)$this->db->lastInsertId();$this->event($orderId,'point_of_sale',null,'fulfilled',$data['note']??null,$actor);(new FinancialPostingCoordinator($this->db))->postIncoming('catalog_payment_attempt',$paymentId,(int)$account['id'],'uniforms',(string)$total,$actor,(string)($data['payment_reference']??$ref));$this->db->commit();Logger::audit('catalog_point_of_sale','catalog_order',$orderId,'Physical catalogue sale completed',['order_reference'=>$ref,'amount'=>$total,'channel'=>$channel,'staff_buyer_id'=>$staffBuyer?:null,'student_id'=>$studentId]);return $this->order($orderId);}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }

    public function confirmByReference(string $reference,float $amount,string $provider,string $providerRef,int $actor=0): bool
    {
        $normalized=(new ReferenceNormalizer())->reference($reference);$s=$this->db->prepare('SELECT * FROM catalog_payment_attempts WHERE idempotency_reference=? OR idempotency_reference=? LIMIT 1');$s->execute([$reference,$normalized]);$payment=$s->fetch(PDO::FETCH_ASSOC);if(!$payment)return false;if($payment['status']==='confirmed')return true;if(abs((float)$payment['amount']-$amount)>.01)return false;$this->confirmOrder((int)$payment['order_id'],(int)$payment['id'],$providerRef,$actor);return true;
    }

    public function confirmOrder(int $orderId,int $paymentId,string $providerRef,int $actor=0): array
    {
        $this->db->beginTransaction();try{$s=$this->db->prepare('SELECT * FROM catalog_orders WHERE id=? FOR UPDATE');$s->execute([$orderId]);$order=$s->fetch(PDO::FETCH_ASSOC);if(!$order)throw new RuntimeException('Order not found');if($order['payment_status']==='paid'){$this->db->commit();return $order;}$lines=$this->db->prepare('SELECT * FROM catalog_order_items WHERE order_id=?');$lines->execute([$orderId]);$rows=$lines->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $line){$stock=$this->db->prepare('SELECT quantity_available,quantity_reserved FROM uniform_sizes WHERE id=? FOR UPDATE');$stock->execute([$line['size_id']]);$q=$stock->fetch(PDO::FETCH_ASSOC);if(!$q||(int)$q['quantity_available']<(int)$line['quantity']||(int)$q['quantity_reserved']<(int)$line['quantity'])throw new RuntimeException('Reserved stock is inconsistent for '.$line['product_title']);$this->db->prepare('UPDATE uniform_sizes SET quantity_available=quantity_available-?,quantity_reserved=quantity_reserved-?,quantity_sold=quantity_sold+? WHERE id=?')->execute([$line['quantity'],$line['quantity'],$line['quantity'],$line['size_id']]);$this->db->prepare('UPDATE inventory_items SET current_quantity=GREATEST(0,current_quantity-?) WHERE id=?')->execute([$line['quantity'],$line['item_id']]);if(!empty($order['student_id']))$this->db->prepare("INSERT INTO uniform_sales(student_id,item_id,size,quantity,unit_price,payment_status,sale_date,received_date,receipt_no,sold_by,notes) VALUES(?,?,?,?,?,'paid',CURDATE(),CURDATE(),?,?,?)")->execute([$order['student_id'],$line['item_id'],$line['size_label'],$line['quantity'],$line['unit_price'],$order['order_reference'].'-'.$line['id'],$order['placed_by'], 'Online catalogue order '.$order['order_reference']]);}
            $this->db->prepare("UPDATE catalog_orders SET status='paid',payment_status='paid',paid_at=NOW() WHERE id=?")->execute([$orderId]);$this->db->prepare("UPDATE catalog_payment_attempts SET status='confirmed',provider_transaction_id=?,confirmed_at=NOW() WHERE id=?")->execute([$providerRef,$paymentId]);$this->event($orderId,'payment_confirmed',$order['status'],'paid',$providerRef,$actor);$payment=$this->payment($paymentId);if(!empty($payment['financial_account_id']))(new FinancialPostingCoordinator($this->db))->postIncoming('catalog_payment_attempt',$paymentId,(int)$payment['financial_account_id'],'uniforms',(string)$order['total_amount'],$actor,$providerRef);$this->db->commit();Logger::audit('catalog_payment_confirmed','catalog_order',$orderId,'Catalogue payment confirmed',['order_reference'=>$order['order_reference'],'amount'=>$order['total_amount'],'provider'=>$payment['channel']??null]);return $this->order($orderId);
        }catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }

    public function cancel(int $orderId,string $type,int $buyerId,int $actor=0): array
    {
        $this->db->beginTransaction();try{$s=$this->db->prepare('SELECT * FROM catalog_orders WHERE id=? FOR UPDATE');$s->execute([$orderId]);$o=$s->fetch(PDO::FETCH_ASSOC);if(!$o||($o['buyer_type']!==$type||(int)$o['buyer_id']!==$buyerId))throw new RuntimeException('Order not found');if(!in_array($o['status'],['pending_payment','payment_processing'],true))throw new RuntimeException('This order can no longer be cancelled');$lines=$this->db->prepare('SELECT size_id,quantity FROM catalog_order_items WHERE order_id=?');$lines->execute([$orderId]);foreach($lines as $line)$this->db->prepare('UPDATE uniform_sizes SET quantity_reserved=GREATEST(0,quantity_reserved-?) WHERE id=?')->execute([$line['quantity'],$line['size_id']]);$this->db->prepare("UPDATE catalog_orders SET status='cancelled',payment_status=IF(payment_status='paid','refunded','failed') WHERE id=?")->execute([$orderId]);$this->event($orderId,'order_cancelled',$o['status'],'cancelled',null,$actor);$this->db->commit();Logger::audit('catalog_order_cancelled','catalog_order',$orderId,'Catalogue order cancelled and reservations released',['order_reference'=>$o['order_reference'],'buyer_type'=>$type,'buyer_id'=>$buyerId]);return $this->order($orderId);}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }

    public function orders(string $type,int $buyerId): array { $this->buyer($type,$buyerId);$s=$this->db->prepare('SELECT * FROM catalog_orders WHERE buyer_type=? AND buyer_id=? ORDER BY created_at DESC');$s->execute([$type,$buyerId]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r)$r['items']=$this->orderItems((int)$r['id']);return $rows; }
    public function order(int $id): array { $s=$this->db->prepare('SELECT * FROM catalog_orders WHERE id=?');$s->execute([$id]);$o=$s->fetch(PDO::FETCH_ASSOC);if(!$o)throw new RuntimeException('Order not found');$o['items']=$this->orderItems($id);return $o; }
    private function orderItems(int $id): array {$s=$this->db->prepare('SELECT * FROM catalog_order_items WHERE order_id=? ORDER BY id');$s->execute([$id]);return $s->fetchAll(PDO::FETCH_ASSOC);}
    private function payment(int $id): array {$s=$this->db->prepare('SELECT * FROM catalog_payment_attempts WHERE id=?');$s->execute([$id]);return $s->fetch(PDO::FETCH_ASSOC)?:[];}
    private function event(int $id,string $type,?string $from,?string $to,?string $note,int $actor): void {$this->db->prepare('INSERT INTO catalog_order_events(order_id,event_type,from_status,to_status,note,actor_user_id) VALUES(?,?,?,?,?,?)')->execute([$id,$type,$from,$to,$note,$actor?:null]);}

    public function reviews(int $productId): array
    {
        $s=$this->db->prepare("SELECT r.id,r.rating,r.title,r.comment,r.verified_purchase,r.created_at,r.buyer_type,CASE WHEN r.buyer_type='parent' THEN COALESCE((SELECT CONCAT(pe.first_name,' ',LEFT(pe.last_name,1),'.') FROM parents pa JOIN persons pe ON pe.id=pa.person_id WHERE pa.id=r.buyer_id),'Parent') ELSE COALESCE((SELECT CONCAT(pe.first_name,' ',LEFT(pe.last_name,1),'.') FROM users u JOIN persons pe ON pe.id=u.person_id WHERE u.id=r.buyer_id),'Staff member') END reviewer_name,(SELECT COUNT(*) FROM catalog_review_helpful h WHERE h.review_id=r.id) helpful_count FROM catalog_reviews r WHERE r.product_id=? AND r.status='published' ORDER BY r.created_at DESC");$s->execute([$productId]);return $s->fetchAll(PDO::FETCH_ASSOC);
    }
    public function saveReview(string $type,int $buyerId,array $data): array
    {
        $this->buyer($type,$buyerId);$product=(int)($data['product_id']??0);$rating=(int)($data['rating']??0);if($rating<1||$rating>5)throw new RuntimeException('Rating must be between 1 and 5');$this->product($product,$type);$v=$this->db->prepare("SELECT 1 FROM catalog_orders o JOIN catalog_order_items oi ON oi.order_id=o.id WHERE o.buyer_type=? AND o.buyer_id=? AND oi.product_id=? AND o.payment_status='paid' LIMIT 1");$v->execute([$type,$buyerId,$product]);$verified=$v->fetchColumn()?1:0;$this->db->prepare("INSERT INTO catalog_reviews(product_id,buyer_type,buyer_id,rating,title,comment,status,verified_purchase) VALUES(?,?,?,?,?,?,'pending',?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),title=VALUES(title),comment=VALUES(comment),status='pending',verified_purchase=VALUES(verified_purchase),updated_at=NOW()")->execute([$product,$type,$buyerId,$rating,trim((string)($data['title']??''))?:null,trim((string)($data['comment']??''))?:null,$verified]);Logger::audit('catalog_review_submitted','catalog_product',$product,'Product review submitted for moderation',['buyer_type'=>$type,'buyer_id'=>$buyerId,'rating'=>$rating,'verified_purchase'=>(bool)$verified]);return ['submitted'=>true,'status'=>'pending','verified_purchase'=>(bool)$verified];
    }

    public function management(array $filters=[]): array
    {
        $where='1=1';$args=[];
        if(!empty($filters['status'])){$where.=' AND o.status=?';$args[]=$filters['status'];}
        $s=$this->db->prepare("SELECT o.*,CASE WHEN o.buyer_type='staff' THEN (SELECT CONCAT(p.first_name,' ',p.last_name) FROM users u JOIN persons p ON p.id=u.person_id WHERE u.id=o.buyer_id) WHEN o.buyer_type='parent' THEN (SELECT CONCAT(p.first_name,' ',p.last_name) FROM parents pa JOIN persons p ON p.id=pa.person_id WHERE pa.id=o.buyer_id) ELSE 'Walk-in customer' END buyer_name,(SELECT COUNT(*) FROM catalog_order_items oi WHERE oi.order_id=o.id) line_count FROM catalog_orders o WHERE $where ORDER BY o.created_at DESC LIMIT 500");
        $s->execute($args);$orders=$s->fetchAll(PDO::FETCH_ASSOC);foreach($orders as &$order)$order['items']=$this->orderItems((int)$order['id']);unset($order);
        $summary=$this->db->query("SELECT COUNT(*) orders,COALESCE(SUM(total_amount),0) value,COALESCE(SUM(payment_status='paid'),0) paid_orders,COALESCE(SUM(status IN ('paid','preparing','ready')),0) awaiting_fulfilment,COALESCE(SUM(source='online'),0) online_orders,COALESCE(SUM(source='internal'),0) internal_orders,COALESCE(SUM(source='physical'),0) physical_orders FROM catalog_orders")->fetch(PDO::FETCH_ASSOC);
        $legacy=$this->db->query("SELECT COUNT(*) physical_sales,COALESCE(SUM(quantity*unit_price),0) physical_value FROM uniform_sales")->fetch(PDO::FETCH_ASSOC);
        $engagement=$this->db->query("SELECT (SELECT COUNT(*) FROM catalog_wishlists) wishlist_count,(SELECT COUNT(*) FROM catalog_reviews WHERE status='pending') pending_reviews,(SELECT ROUND(AVG(rating),2) FROM catalog_reviews WHERE status='published') average_rating")->fetch(PDO::FETCH_ASSOC);
        $reviews=$this->db->query("SELECT r.*,p.title product_title,CASE WHEN r.buyer_type='parent' THEN 'Parent' ELSE 'Staff member' END reviewer_type FROM catalog_reviews r JOIN uniform_catalog_products p ON p.id=r.product_id WHERE r.status='pending' ORDER BY r.created_at LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);
        $products=$this->db->query("SELECT p.id,p.title,(SELECT COUNT(*) FROM catalog_wishlists w WHERE w.product_id=p.id) wishlist_count,(SELECT COUNT(*) FROM catalog_reviews r WHERE r.product_id=p.id AND r.status='published') review_count,(SELECT ROUND(AVG(r.rating),2) FROM catalog_reviews r WHERE r.product_id=p.id AND r.status='published') rating,(SELECT COALESCE(SUM(oi.quantity),0) FROM catalog_order_items oi JOIN catalog_orders o ON o.id=oi.order_id WHERE oi.product_id=p.id AND o.payment_status='paid') units_sold,(SELECT COALESCE(SUM(us.quantity_available),0) FROM uniform_sizes us WHERE us.item_id=p.item_id OR us.item_id IN (SELECT v.item_id FROM uniform_catalog_variants v WHERE v.product_id=p.id AND v.status='active')) available_stock,(SELECT COALESCE(SUM(us.quantity_reserved),0) FROM uniform_sizes us WHERE us.item_id=p.item_id OR us.item_id IN (SELECT v.item_id FROM uniform_catalog_variants v WHERE v.product_id=p.id AND v.status='active')) reserved_stock FROM uniform_catalog_products p ORDER BY units_sold DESC,wishlist_count DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);
        return ['orders'=>$orders,'summary'=>array_merge($summary,$legacy),'engagement'=>$engagement,'pending_reviews'=>$reviews,'product_analytics'=>$products];
    }

    public function updateOrderStatus(int $id,string $status,int $actor,?string $note=null): array
    {
        if(!in_array($status,['preparing','ready','fulfilled','cancelled'],true))throw new RuntimeException('Invalid fulfilment status');$o=$this->order($id);if($status==='cancelled')return $this->cancel($id,$o['buyer_type'],(int)$o['buyer_id'],$actor);if($o['payment_status']!=='paid')throw new RuntimeException('Only paid orders can enter fulfilment');$this->db->prepare("UPDATE catalog_orders SET status=?,fulfilled_at=IF(?='fulfilled',NOW(),fulfilled_at) WHERE id=?")->execute([$status,$status,$id]);$this->event($id,'status_changed',$o['status'],$status,$note,$actor);Logger::audit('catalog_order_status_changed','catalog_order',$id,'Catalogue fulfilment status changed',['from'=>$o['status'],'to'=>$status]);return $this->order($id);
    }

    public function moderateReview(int $id,string $status,int $actor): array { if(!in_array($status,['published','rejected'],true))throw new RuntimeException('Invalid review decision');$this->db->prepare('UPDATE catalog_reviews SET status=?,moderated_by=?,moderated_at=NOW() WHERE id=?')->execute([$status,$actor,$id]);Logger::audit('catalog_review_moderated','catalog_review',$id,'Product review moderation completed',['decision'=>$status]);return ['id'=>$id,'status'=>$status]; }
}
